package mcp

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http/httptest"
	"os"
	"sort"
	"strings"
	"testing"
	"time"

	"github.com/nevzatcirak/cirak/internal/mcpclient"
	"github.com/nevzatcirak/cirak/internal/security"
)

// ADR-026 section 8 (S1): the rename must not touch the tool contract. The golden file holds the
// whole tool surface with every optional tool registered (name, description, annotations, input
// and output schema), captured on `main` before the rename. A change to it is a contract change
// and needs its own decision; it is never regenerated by a rename.
const toolContractGolden = "testdata/tool_contract.golden.json"

func fullToolSurface(t *testing.T) []byte {
	t.Helper()
	s := &Server{
		Token:           strings.Repeat("t", 32),
		Catalog:         &CatalogConfig{Roots: &security.LifecycleRoots{}},
		Create:          &CreateConfig{},
		Archive:         &ArchiveConfig{},
		PermissionRelay: &PermissionRelayConfig{Mode: relayModeRejectOnly},
	}
	ts := httptest.NewServer(s)
	t.Cleanup(ts.Close)
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	client, err := mcpclient.Connect(ctx, ts.URL, s.Token)
	if err != nil {
		t.Fatal(err)
	}
	defer client.Close()
	tools, err := client.ListTools(ctx, nil)
	if err != nil {
		t.Fatal(err)
	}
	sort.Slice(tools.Tools, func(i, j int) bool { return tools.Tools[i].Name < tools.Tools[j].Name })
	raw, err := json.Marshal(tools.Tools)
	if err != nil {
		t.Fatal(err)
	}
	var out bytes.Buffer
	if err := json.Indent(&out, raw, "", "  "); err != nil {
		t.Fatal(err)
	}
	out.WriteByte('\n')
	return out.Bytes()
}

func TestToolContractGolden(t *testing.T) {
	got := fullToolSurface(t)
	if os.Getenv("HB_GOLDEN_WRITE") == "1" { // capture tool for the pre-rename tree only
		if err := os.WriteFile(toolContractGolden, got, 0o644); err != nil {
			t.Fatal(err)
		}
		return
	}
	want, err := os.ReadFile(toolContractGolden)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, want) {
		t.Fatalf("the tool contract changed (%d bytes, golden %d bytes): a rename must keep every tool name, description, annotation and schema byte-identical", len(got), len(want))
	}
	var tools []struct{ Name string }
	if err := json.Unmarshal(got, &tools); err != nil || len(tools) != 17 {
		t.Fatalf("the full surface lists %d tools (want 17: the 11 default, list_catalog, create_session, three archive tools, reply_permission): %v", len(tools), err)
	}
}
